import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import test from "node:test";
import { Cents, Percentage } from "../dist/money.js";

// Vectors generated by the Rust primitives (rust/sdk/tests/money_vectors.rs).
const vectors = JSON.parse(readFileSync(new URL("../../validation/x7e-money-vectors.json", import.meta.url), "utf8"));

const ops = {
  "cents.new": ([v]) => Cents.new(v).value.toString(),
  "cents.encode": ([v]) => Cents.new(v).encode().toString(),
  "cents.decode": ([v]) => Cents.decode(v).value.toString(),
  "cents.from_dollars": ([d]) => Cents.fromDollars(d).value.toString(),
  "cents.checked_sub": ([a, b]) => Cents.new(a).checkedSub(Cents.new(b)).value.toString(),
  "cents.min": ([a, b]) => Cents.new(a).min(Cents.new(b)).value.toString(),
  "cents.as_currency": ([v]) => Cents.new(v).asCurrency(),
  "cents.as_saving": ([v]) => Cents.new(v).asSaving(),
  "percentage.from_whole": ([v]) => String(Percentage.fromWhole(Number(v)).basisPoints),
  "percentage.from_basis_points": ([v]) => String(Percentage.fromBasisPoints(Number(v)).basisPoints),
  "percentage.decode": ([v]) => String(Percentage.decode(v).basisPoints),
  "percentage.encode": ([v]) => String(Percentage.fromBasisPoints(Number(v)).encode()),
  "percentage.of": ([bp, amount]) => Percentage.fromBasisPoints(Number(bp)).of(Cents.new(amount)).value.toString(),
};

// Integer arguments as bigint (exact), and as number whenever that is exact.
function argumentSets(args) {
  const exact = args.map((a) => BigInt(a));
  const sets = [exact];
  if (exact.every((a) => a <= BigInt(Number.MAX_SAFE_INTEGER))) sets.push(exact.map(Number));
  return sets;
}

test("TypeScript Cents/Percentage equal the Rust vectors", () => {
  assert.equal(vectors.format, "axiom-x7e-money-vectors/v1");
  assert.ok(vectors.cases.length >= 90);
  const seen = new Set();
  for (const vector of vectors.cases) {
    seen.add(vector.op);
    const run = ops[vector.op];
    assert.ok(run, `unknown op ${vector.op}`);
    for (const args of argumentSets(vector.args)) {
      const label = `${vector.op}(${vector.args.join(", ")}) [${typeof args[0]}]`;
      if ("ok" in vector) {
        assert.equal(run(args), vector.ok, label);
      } else {
        assert.throws(() => run(args), (error) => error instanceof RangeError && error.message === vector.error, label);
      }
    }
  }
  assert.deepEqual([...seen].sort(), Object.keys(ops).sort());
});

test("numbers never lose precision; wrong types are TypeErrors", () => {
  assert.throws(() => Cents.new(2 ** 60), RangeError, "an unsafe number is refused, not rounded");
  assert.throws(() => Cents.new(-1), RangeError);
  assert.throws(() => Cents.new(1.5), TypeError);
  assert.throws(() => Cents.new("5"), TypeError);
  assert.equal(Cents.new(2n ** 60n).encode(), 2n ** 60n);
  assert.equal(Cents.new(Number.MAX_SAFE_INTEGER).encode(), Number.MAX_SAFE_INTEGER);
  assert.throws(() => Cents.new(2n ** 53n).toNumber(), RangeError);
  assert.equal(Cents.new(42).toNumber(), 42);
  assert.throws(() => Cents.decode(-1), { name: "TypeError", message: "expected unsigned integer, received signed integer" });
  assert.throws(() => Cents.decode("12"), { name: "TypeError", message: "expected unsigned integer, received string" });
  assert.throws(() => Percentage.fromWhole(1.5), RangeError);
  assert.throws(() => Percentage.fromBasisPoints(-1), RangeError);
  assert.throws(() => Percentage.fromWhole("50"), TypeError);
});

test("values are immutable and comparable", () => {
  const price = Cents.new(1999);
  assert.ok(Object.isFrozen(price));
  assert.equal(price.toString(), "$19.99");
  assert.ok(price.equals(Cents.new(1999n)));
  assert.equal(Cents.ZERO.compare(price), -1);
  assert.equal(price.min(Cents.ZERO), Cents.ZERO);
  assert.equal(Percentage.fromWhole(25).compare(Percentage.fromBasisPoints(2500)), 0);
  assert.ok(Percentage.fromWhole(25).equals(Percentage.fromBasisPoints(2500)));
});

// Verifier finding M-2 (unit w1-f2): no silent coercion, no silent data loss.
test("no implicit coercion: operators, template strings, Number() and JSON throw", async () => {
  const { encodeValue } = await import("../dist/index.js");
  const a = Cents.new(1000);
  const b = Cents.new(999);
  const p = Percentage.fromWhole(10);
  const coercion = { name: "TypeError", message: /cannot be converted to a primitive.*\.compare\(\)\/\.lt\(\).*\.toString\(\).*\.encode\(\)/ };
  for (const value of [a, p]) {
    assert.throws(() => value < b, coercion, "`<` used to compare currency strings");
    assert.throws(() => value >= b, coercion);
    assert.throws(() => value + 1, coercion);
    assert.throws(() => value == 1000, coercion);
    assert.throws(() => `${value}`, coercion);
    assert.throws(() => String(value), coercion);
    assert.throws(() => Number(value), coercion);
    assert.throws(() => +value, coercion);
    assert.throws(() => JSON.stringify(value), { name: "TypeError", message: /cannot be serialized implicitly: call \.encode\(\)/ });
    assert.throws(() => JSON.stringify({ price: value }), TypeError);
    // encodeValue used to give {"Record":[]} and an empty record field.
    assert.throws(() => encodeValue(value), { name: "TypeError", message: /is not a plain Axiom value: call \.encode\(\)/ });
    assert.throws(() => encodeValue({ price: value }), TypeError);
    assert.throws(() => encodeValue([value]), TypeError);
  }
  // The explicit forms work and are exact.
  assert.deepEqual(encodeValue({ price: a.encode() }), { Record: [{ name: "price", value: { Unsigned: 1000 } }] });
  assert.deepEqual(encodeValue(Cents.new(2n ** 64n - 1n).encode()), { Unsigned: "18446744073709551615" });
  assert.equal(JSON.stringify({ price: a.encode(), rate: p.encode() }), '{"price":1000,"rate":1000}');
  assert.deepEqual([a.lt(b), a.le(b), a.gt(b), a.ge(b), a.lt(a), a.le(a)], [false, false, true, true, false, true]);
  assert.deepEqual([p.lt(Percentage.fromWhole(11)), p.ge(Percentage.fromBasisPoints(1000)), p.gt(p)], [true, true, false]);
  assert.equal(a.toString(), "$10.00");
  assert.equal(p.toString(), "Percentage(basis_points=1000)");
  assert.equal([Cents.new(5), Cents.new(30), Cents.new(100)].sort((x, y) => x.compare(y)).map((c) => c.asCurrency()).join(","), "$0.05,$0.30,$1.00");
});

test("instances, classes and prototypes are frozen; constructors are module-private", () => {
  const evil = Cents.new(1);
  assert.throws(() => { Cents.ZERO = evil; }, TypeError);
  assert.throws(() => { Cents.new = () => evil; }, TypeError);
  assert.throws(() => { Cents.prototype.asCurrency = () => "$0.00"; }, TypeError);
  assert.throws(() => { Percentage.fromWhole = () => null; }, TypeError);
  assert.throws(() => { Percentage.prototype.of = () => evil; }, TypeError);
  assert.ok(Object.isFrozen(Cents) && Object.isFrozen(Cents.prototype) && Object.isFrozen(Percentage) && Object.isFrozen(Percentage.prototype));
  assert.equal(Cents.ZERO.value, 0n);
  // The TypeScript-private constructor used to accept `new Cents(-5n)` and print "$0.-5".
  assert.throws(() => new Cents(-5n), { name: "TypeError", message: /use Cents\.new\(\)/ });
  assert.throws(() => new Percentage(-5), { name: "TypeError", message: /use Percentage\.fromWhole\(\)/ });
  // Wrong operand types are TypeErrors, not property lookups on garbage.
  assert.throws(() => evil.min(5), { name: "TypeError", message: "expected Cents" });
  assert.throws(() => evil.checkedSub({ value: 1n }), { name: "TypeError", message: "expected Cents" });
  assert.throws(() => evil.compare(Object.create(Cents.prototype)), { name: "TypeError", message: "expected Cents" });
  assert.throws(() => evil.equals(null), { name: "TypeError", message: "expected Cents" });
  assert.throws(() => Percentage.fromWhole(5).of(5), { name: "TypeError", message: "expected Cents" });
  assert.throws(() => Percentage.fromWhole(5).compare(evil), { name: "TypeError", message: "expected Percentage" });
});

test("Cents and Percentage are exported from the package root and the ./money subpath", async () => {
  const root = await import("../dist/index.js");
  assert.equal(root.Cents, Cents);
  assert.equal(root.Percentage, Percentage);
  const pkg = JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf8"));
  assert.deepEqual(pkg.exports["./money"], { types: "./dist/money.d.ts", default: "./dist/money.js" });
  // Self-reference through the package name resolves the subpath exactly as a consumer would.
  const sub = await import("@axiomcore/extension-sdk/money");
  assert.equal(sub.Cents, Cents);
  const viaName = await import("@axiomcore/extension-sdk");
  assert.equal(viaName.Percentage, Percentage);
});
